ok=[]; bad=[]
for i in range(32,127):
    ch=chr(i)
    src = "`x\\%s y`;" % ch
    c,o,e = run(src)
    if c==0: ok.append((ch,repr(o)))
    else: bad.append(ch)
print("ESCAPE OK:", ok)
print("ESCAPE FAIL:", "".join(bad))
